# Builds benchmarks/eco_2x2/results/report.md from summary.csv and units.csv.
#   Rscript benchmarks/eco_2x2/make_report.R
dir <- file.path("benchmarks", "eco_2x2", "results")
S <- read.csv(file.path(dir, "summary.csv")); U <- read.csv(file.path(dir, "units.csv"))
f3 <- function(x) ifelse(is.na(x), "", formatC(x, format = "f", digits = 3))
fg <- function(x) ifelse(is.na(x), "", formatC(x, format = "g", digits = 3))
out <- c("# eiDPM vs eco: 2x2 benchmark on `reg` and `census`", "",
         "Generated by `make_report.R` from `summary.csv` and `units.csv` (written by `run_benchmark.R`).", "",
         "* `agg` = size-weighted aggregate rate, `mean` = unweighted in-sample mean of unit rates.",
         "* `ESS/s` = bulk effective sample size of the aggregate per CPU-second (all chains, warm-up and compilation excluded only where noted).",
         "* `z vs eco` = difference from eco's posterior mean in units of the combined Monte Carlo SE; pass = |z| <= 3 or |diff| <= 0.005.",
         "* `chain sd` = SD of per-chain posterior means (a direct check of between-chain agreement).", "")
for (dn in unique(S$data)) for (as in unique(S$assumption)) for (md in unique(S$model)) {
  s <- S[S$data == dn & S$assumption == as & S$model == md, ]
  if (!nrow(s)) next
  out <- c(out, sprintf("## %s, %s, %s", dn, as, md), "")
  for (q in c("agg_W1", "agg_W2", "mean_W1", "mean_W2")) {
    r <- s[s$quantity == q, ]
    out <- c(out, sprintf("**%s**: truth %s; Duncan-Davis [%s, %s]", q, f3(r$truth[1]), f3(r$dd_lower[1]), f3(r$dd_upper[1])), "",
             "| method | mean | 90% interval | chain sd | R-hat | ESS | CPU s | ESS/s | z vs eco | pass |",
             "|---|---|---|---|---|---|---|---|---|---|")
    for (k in seq_len(nrow(r)))
      out <- c(out, sprintf("| %s | %s | [%s, %s] | %s | %s | %s | %s | %s | %s | %s |",
                            r$method[k], f3(r$mean[k]), f3(r$q05[k]), f3(r$q95[k]), f3(r$chain_mean_sd[k]),
                            f3(r$rhat[k]), fg(r$ess_bulk[k]), fg(r$cpu_seconds[k]), fg(r$ess_per_cpu_s[k]),
                            f3(r$z_vs_eco[k]), ifelse(is.na(r$pass_mean[k]), "", r$pass_mean[k])))
    out <- c(out, "")
  }
  u <- U[U$data == dn & U$assumption == as & U$model == md, ]
  out <- c(out, "Unit level:", "", "| method | RMSE W1 | RMSE W2 | 90% cover W1 | 90% cover W2 | cor with eco (W1) | pass |",
           "|---|---|---|---|---|---|---|")
  for (k in seq_len(nrow(u)))
    out <- c(out, sprintf("| %s | %s | %s | %s | %s | %s | %s |", u$method[k], f3(u$rmse_W1[k]), f3(u$rmse_W2[k]),
                          f3(u$cover90_W1[k]), f3(u$cover90_W2[k]), f3(u$cor_eco_W1[k]),
                          ifelse(is.na(u$pass_cor[k]), "", u$pass_cor[k])))
  ex <- s[s$quantity == "agg_W1" & s$method != "eco", c("method", "alpha_med", "pi_last_q99", "divergences")]
  if (md == "DP") {
    out <- c(out, "", "Sampler diagnostics: ", "")
    for (k in seq_len(nrow(ex)))
      out <- c(out, sprintf("* %s: median alpha %s; 99th pct of last-component mass %s; divergences %s",
                            ex$method[k], fg(ex$alpha_med[k]), fg(ex$pi_last_q99[k]),
                            ifelse(is.na(ex$divergences[k]), "n/a", ex$divergences[k])))
  }
  out <- c(out, "")
}
writeLines(out, file.path(dir, "report.md"))
cat("wrote", file.path(dir, "report.md"), "\n")
